let DATA;const $=s=>document.querySelector(s);const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];const fmt=n=>Number(n).toLocaleString('en-US');
function renderHeat(){const year=+$('#year').value,type=$('#type').value,mode=$('#mode').value;const parks=DATA.parks.filter(p=>type==='all'||p.type===type);$('#heat-label').textContent=`${year} · ${mode==='relative'?'each park’s peak = 100%':'reported park visits'}`;$('#heatmap').innerHTML=`<table><caption class="sr-only">Monthly park visits in ${year}. Each cell’s color is relative to that park’s peak month.</caption><thead><tr><th scope="col">Park / community</th>${months.map(m=>`<th scope="col">${m}</th>`).join('')}</tr></thead><tbody>${parks.map(p=>{const a=p.visits[year],max=Math.max(...a);return `<tr><th scope="row">${p.name}<small>${p.community}${p.role==='Reference'?' · reference':''}</small></th>${a.map((v,i)=>{const r=v/max,notOpen=p.id==='rockin'&&year===2024&&i===0;return `<td class="heat-cell" style="background:color-mix(in srgb, #24594b ${Math.round(r*100)}%, #f3f7f0);color:${r>.55?'white':'#183129'}" title="${p.name}, ${months[i]} ${year}: ${fmt(v)} visits${notOpen?' (not yet open)':''}">${notOpen?'—':mode==='relative'?Math.round(r*100)+'%':fmt(v)}</td>`}).join('')}</tr>`}).join('')}</tbody></table>`;}
fetch('data/site-data.json').then(r=>{if(!r.ok)throw Error('Dataset unavailable');return r.json()}).then(d=>{DATA=d;renderHeat();initializeStory();['year','type','mode'].forEach(id=>$('#'+id).addEventListener('change',renderHeat));$('#reset').addEventListener('click',()=>{$('#year').value='2025';$('#type').value='all';$('#mode').value='relative';renderHeat()})}).catch(()=>{$('#heatmap').innerHTML='<p>The data could not load. Please reload the page. The collected dataset is available through the Google Drive files link in the header.</p>'});
